class Solution {
public:
    string smallestSubsequence(string s,int k,char letter,int repetition){
        int remain=count(s.begin(),s.end(),letter),need=repetition;
        string st;int n=s.size();
        for(int i=0;i<n;++i){char c=s[i];
            while(!st.empty()&&st.back()>c&&
                  (int)st.size()-1+(n-i)>=k&&
                  (st.back()!=letter||remain>need)){
                if(st.back()==letter)++need;
                st.pop_back();
            }
            if((int)st.size()<k){
                if(c==letter){st+=c;--need;}
                else if(k-(int)st.size()>need)st+=c;
            }
            if(c==letter)--remain;
        }
        return st;
    }
};
